const TROPICO = 'tropico-latino';
const FRASI_TROPICO = 'Vi aspettiamo stasera in via Mazzini 77/A | Prenota il tuo tavolo: 0523 335932 | Margarita frozen o classico? | Aperitivo al bancone, si parte! | Due sale, più di 100 posti: portate tutti | Bienvenidos al Tropico! | Fajitas per due: si divide e si assaggia | Nachos e guacamole per cominciare | Anche vegetariano: burrito de verduras | Enchiladas rojas o verdes? Scegli tu | Queso fundido da condividere al tavolo | Venerdì e sabato aperti fino alle 2 | Cucina aperta fino alle 23, nel weekend 23:30 | Per finire in dolcezza: churros | Mousse al cioccolato e peperoncino, da provare';
const LINK_TROPICO = 'https://wa.me/393312173684';
const PUNTI = ['a', 'b', 'c', 'd', 'e', 'f', 'g'];
const ID_NUOVA_SCHEDA = 2026112201; // sheetId scelto da noi, così addSheet e intestazioni stanno in UNA chiamata atomica

const cfg = () => $('Config').first().json;
const modalitaVera = () => String(cfg().MODALITA || '').trim() === 'vero'; // qualunque altro valore = prova
const lettera = (i) => { let s = ''; let n = i + 1; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const intervallo = (titolo, a1) => `'${titolo.replace(/'/g, "''")}'` + (a1 ? `!${a1}` : '');
const urlFoglio = () => API + encodeURIComponent(cfg().SHEET_ID);
const cella = (riga, i) => (riga && riga[i] != null ? String(riga[i]) : '');
const vuota = (v) => String(v == null ? '' : v).trim() === '';
const virgolette = (v) => '«' + (String(v).length > 30 ? String(v).slice(0, 30) + '…' : String(v)) + '»';

