  const u = urlFoglio();
  return [
    { cosa: 'meta', url: `${u}?fields=sheets.properties` },
    { cosa: 'clienti', url: `${u}/values/${encodeURIComponent(intervallo(CLIENTI))}` },
    { cosa: 'calendario', url: `${u}/values/${encodeURIComponent(intervallo(CALENDARIO))}` },
    { cosa: 'approvazioni', url: `${u}/values/${encodeURIComponent(intervallo(APPROVAZIONI, '1:1'))}` },
  ];
}

// Esito di una risposta dell'HTTP Request (fullResponse + neverError, oppure {error} se la rete è caduta).
function esito(r) {
  if (!r) return { ok: false, errore: 'nessuna risposta' };
  if (r.error) return { ok: false, errore: 'rete: ' + String(r.error.message || r.error.description || JSON.stringify(r.error)).slice(0, 160) };
  const sc = Number(r.statusCode);
  if (sc >= 200 && sc < 300) return { ok: true, body: r.body || {} };
  const msg = r.body && r.body.error && r.body.error.message ? String(r.body.error.message) : String(r.statusMessage || '');
  return { ok: false, errore: `HTTP ${sc || '?'}: ${msg.slice(0, 160)}` };
}

// Mette insieme le risposte delle letture (stesso ordine delle richieste).
function leggiStato(richieste, risposte) {
  const s = { meta: null, valori: {}, errori: {} };
  richieste.forEach((q, i) => {
    const e = esito(risposte[i]);
    if (!e.ok) { s.errori[q.cosa] = e.errore; s.valori[q.cosa] = null; return; }
    if (q.cosa === 'meta') {
      s.meta = {};
      for (const sh of e.body.sheets || []) { const p = sh.properties || {}; s.meta[p.title] = { sheetId: p.sheetId, colonne: (p.gridProperties || {}).columnCount || 0 }; }
    } else s.valori[q.cosa] = e.body.values || [];
  });
  return s;
}

const fermo = (perche, api = false) => ({ stato: 'fermo', perche, api, struttura: [], valori: [] });
const aPosto = () => ({ stato: 'gia', struttura: [], valori: [] });
const errLettura = (s, cosa) => fermo(`non riesco a leggere (${s.errori[cosa] || s.errori.meta || 'errore'})`, true);

// Colonne nuove di Clienti: a) le 3 colonne, f) anteprime_con_persone. Stanno in fondo, una dopo l'altra:
// le posizioni si calcolano INSIEME (prima quelle di a, poi f) e la modifica di griglia/formato va in UN solo batchUpdate,
// sul punto a se ha qualcosa da fare, altrimenti sul punto f. Così due chiamate parallele non si pestano i piedi.
function colonneClienti(s) {
  if (!s.meta) return { fermo: errLettura(s, 'meta') };
  const m = s.meta[CLIENTI];
  if (!m) return { fermo: fermo('la scheda Clienti non esiste') };
  const righe = s.valori.clienti;
  if (righe == null) return { fermo: errLettura(s, 'clienti') };
  const int = (righe[0] || []).map((v) => String(v == null ? '' : v));
  const presenti = new Set(int.map((v) => v.trim()));
  const manca = { a: NUOVE_CLIENTI.filter((n) => !presenti.has(n)), f: NUOVE_CLIENTI_F.filter((n) => !presenti.has(n)) };
  const tutte = manca.a.concat(manca.f);
  if (!tutte.length) return { manca };
  let inizio = 0; int.forEach((v, i) => { if (!vuota(v)) inizio = i + 1; });
  if (righe.slice(1).some((r) => (r || []).slice(inizio).some((v) => !vuota(v))))
    return { manca, fermo: fermo(`ci sono dati a destra dell'ultima intestazione (dalla colonna ${lettera(inizio)}): non metto colonne sopra dati esistenti`) };
  const fine = inizio + tutte.length;
  const struttura = [];
  if (fine > m.colonne) struttura.push({ appendDimension: { sheetId: m.sheetId, dimension: 'COLUMNS', length: fine - m.colonne } });
  tutte.forEach((n, k) => {
    if (COLONNE_TESTO.includes(n)) struttura.push({ repeatCell: { range: { sheetId: m.sheetId, startColumnIndex: inizio + k, endColumnIndex: inizio + k + 1 },
      cell: { userEnteredFormat: { numberFormat: { type: 'TEXT', pattern: '@' } } }, fields: 'userEnteredFormat.numberFormat' } });
  });
  // Le intestazioni entrano nello STESSO batchUpdate (repeatCell con il testo, come in c): griglia, formato e nomi
  // nascono insieme o per niente. Così alla rilettura le colonne esistono già per nome e il punto g le ritrova.
  tutte.forEach((n, k) => struttura.push({ repeatCell: { range: { sheetId: m.sheetId, startRowIndex: 0, endRowIndex: 1, startColumnIndex: inizio + k, endColumnIndex: inizio + k + 1 },
    cell: { userEnteredValue: { stringValue: n } }, fields: 'userEnteredValue' } }));
  const allarga = fine > m.colonne ? fine - m.colonne : 0;
  return { manca, inizio, struttura, allarga, padrone: manca.a.length ? 'a' : 'f' };
}

function puntoColonne(s, p) {
  const c = colonneClienti(s);
  if (c.manca && !c.manca[p].length) return aPosto();
  if (c.fermo) return c.fermo;
  const da = c.inizio + (p === 'f' ? c.manca.a.length : 0);
  const nomi = c.manca[p]; const a = da + nomi.length - 1;
  const mia = c.padrone === p;
  const descr = `aggiunta di ${nomi.join(', ')} in ${lettera(da)}1${a > da ? '-' + lettera(a) + '1' : ''}`
    + (nomi.some((n) => COLONNE_TESTO.includes(n)) ? ' (ID in formato testo)' : '')
    + (p === 'f' ? ' (vuota = no, formato normale)' : '')
    + (mia && c.allarga ? `, griglia +${c.allarga} colonne` : '');
  return { stato: 'da_fare', descr, struttura: mia ? c.struttura : [], valori: [], ...(mia ? {} : { dipende: c.padrone }) };
}
const puntoA = (s) => puntoColonne(s, 'a');
const puntoF = (s) => puntoColonne(s, 'f');

function puntoB(s) {
  if (!s.meta) return errLettura(s, 'meta');
  const m = s.meta[CALENDARIO];
  if (!m) return fermo('la scheda Calendario non esiste');
  const righe = s.valori.calendario;
  if (righe == null) return errLettura(s, 'calendario');
  const int = righe[0] || [];
  const diverse = CAL_A_T.map((n, i) => (cella(int, i) === n ? null : `${lettera(i)}1 è ${virgolette(cella(int, i))} invece di ${virgolette(n)}`)).filter(Boolean);
  if (diverse.length) return fermo(`A1:T1 non sono le 20 intestazioni attese (${diverse.slice(0, 3).join('; ')}${diverse.length > 3 ? `; e altre ${diverse.length - 3}` : ''})`);
  const uz = CAL_U_Z.map((n, k) => cella(int, 20 + k));
  if (uz.every((v, k) => v === CAL_U_Z[k])) return aPosto();
  if (!uz.every(vuota)) {
    const altro = uz.map((v, k) => (vuota(v) || v === CAL_U_Z[k] ? null : `${lettera(20 + k)}1 = ${virgolette(v)}`)).filter(Boolean);
    return fermo(altro.length ? `U1:Z1 contengono altro (${altro.join('; ')}): non scrivo` : 'U1:Z1 sono compilate solo in parte: non scrivo, controlla a mano');
  }
  if (righe.slice(1).some((r) => (r || []).slice(20, 26).some((v) => !vuota(v)))) return fermo('ci sono già dati nelle colonne U-Z sotto intestazioni vuote: non scrivo');
  const struttura = m.colonne < 26 ? [{ appendDimension: { sheetId: m.sheetId, dimension: 'COLUMNS', length: 26 - m.colonne } }] : [];
  return { stato: 'da_fare', descr: 'intestazioni stato_2 … errore_2 in U1:Z1' + (struttura.length ? `, griglia +${26 - m.colonne} colonne` : ''),
    struttura, valori: [{ range: intervallo(CALENDARIO, 'U1:Z1'), values: [CAL_U_Z] }] };
}

function puntoC(s) {
  if (!s.meta) return errLettura(s, 'meta');
  const m = s.meta[APPROVAZIONI];
  if (!m) {
    let id = ID_NUOVA_SCHEDA; const usati = new Set(Object.values(s.meta).map((x) => x.sheetId));
    while (usati.has(id)) id += 1;
    const struttura = [{ addSheet: { properties: { sheetId: id, title: APPROVAZIONI, gridProperties: { rowCount: 1000, columnCount: 26 } } } }]
      .concat(APP_INTESTAZIONI.map((n, i) => ({ repeatCell: { range: { sheetId: id, startRowIndex: 0, endRowIndex: 1, startColumnIndex: i, endColumnIndex: i + 1 },
        cell: { userEnteredValue: { stringValue: n } }, fields: 'userEnteredValue' } })));
    return { stato: 'da_fare', descr: 'nuova scheda con le 9 intestazioni (data_ora … dettaglio)', struttura, valori: [] };
  }
  const righe = s.valori.approvazioni;
  if (righe == null) return errLettura(s, 'approvazioni');
  const int = righe[0] || [];
  const diff = APP_INTESTAZIONI.map((n, i) => (cella(int, i) === n ? null : `${lettera(i)}1 è ${virgolette(cella(int, i))} invece di ${virgolette(n)}`)).filter(Boolean);
  int.slice(9).forEach((v, k) => { if (!vuota(v)) diff.push(`${lettera(9 + k)}1 in più: ${virgolette(v)}`); });
  if (!diff.length) return aPosto();
  return fermo(`la scheda esiste già con intestazioni diverse (${diff.slice(0, 4).join('; ')}${diff.length > 4 ? `; e altre ${diff.length - 4}` : ''}): non la tocco`);
}

// La riga di tropico-latino (una sola) e la colonna per nome, nello stato letto.
function cellaTropico(s, colonna) {
  if (!s.meta) return { fermo: errLettura(s, 'meta') };
  if (!s.meta[CLIENTI]) return { fermo: fermo('la scheda Clienti non esiste') };
  const righe = s.valori.clienti;
  if (righe == null) return { fermo: errLettura(s, 'clienti') };
  const int = (righe[0] || []).map((v) => String(v == null ? '' : v).trim());
  const quante = (n) => int.filter((v) => v === n).length;
  if (quante('cliente') !== 1) return { fermo: fermo(quante('cliente') ? 'la colonna cliente compare più volte' : 'manca la colonna cliente') };
  if (quante(colonna) !== 1) return { fermo: fermo(quante(colonna) ? `la colonna ${colonna} compare più volte` : `manca la colonna ${colonna}`) };
  const ic = int.indexOf('cliente'); const col = int.indexOf(colonna);
  const trovate = []; righe.forEach((r, i) => { if (i > 0 && cella(r, ic).trim() === TROPICO) trovate.push(i + 1); });
  if (!trovate.length) return { fermo: fermo(`nessuna riga con cliente = ${TROPICO}`) };
  if (trovate.length > 1) return { fermo: fermo(`${TROPICO} compare in ${trovate.length} righe (righe ${trovate.join(', ')}): non so quale scrivere`) };
  const riga = trovate[0];
  return { riga, attuale: cella(righe[riga - 1], col), range: intervallo(CLIENTI, `${lettera(col)}${riga}`) };
}

function puntoD(s) {
  const t = cellaTropico(s, 'frasi_storie');
  if (t.fermo) return t.fermo;
  if (t.attuale === FRASI_TROPICO) return aPosto();
  return { stato: 'da_fare', descr: `nuovo testo in frasi_storie, riga ${t.riga} (prima: ${t.attuale ? t.attuale.length + ' caratteri' : 'vuota'})`,
    struttura: [], valori: [{ range: t.range, values: [[FRASI_TROPICO]] }] };
}

// e) link_prenotazione. Il numero non entra MAI nella descrizione: né il vecchio né il nuovo.
function puntoE(s) {
  const t = cellaTropico(s, 'link_prenotazione');
  if (t.fermo) return t.fermo;
  if (t.attuale === LINK_TROPICO) return aPosto();
  const prima = vuota(t.attuale) ? '(vuoto)' : (/wa\.me/i.test(t.attuale) ? 'wa.me/… (nascosto)' : '(nascosto)');
  return { stato: 'da_fare', descr: `link_prenotazione: ${prima} → wa.me/… (nascosto), riga ${t.riga}`,
    struttura: [], valori: [{ range: t.range, values: [[LINK_TROPICO]] }] };
}

// g) La lettura da Meta: buona SOLO con status 200 e instagram_business_account.id di sole cifre, 15-20.
// Il motivo è sempre un testo nostro: il messaggio d'errore di Meta non esce mai (al massimo il codice HTTP).
function letturaMeta() {
  let r;
  try { r = $('Leggi Meta').first().json; } catch (e) { return { ok: false, perche: 'lettura da Meta non eseguita' }; }
  if (!r || r.error) return { ok: false, perche: 'lettura da Meta non riuscita (rete)' };
  const sc = Number(r.statusCode);
  if (sc !== 200) return { ok: false, perche: `lettura da Meta non riuscita (codice HTTP ${Number.isFinite(sc) ? sc : '?'})` };
  const iba = r.body && r.body.instagram_business_account;
  const id = iba && iba.id;
  if (typeof id !== 'string') return { ok: false, perche: 'lettura da Meta senza account Instagram collegato (codice HTTP 200)' };
  if (!/^\d{15,20}$/.test(id)) return { ok: false, perche: 'lettura da Meta con un ID Instagram di forma inattesa (codice HTTP 200)' };
  return { ok: true, id };
}

// g) Scrive ig_user_id_2 (letto) e fb_page_id_2 (da Config) nella riga di tropico-latino. MAI ID nei testi.
function puntoG(s, colonneDiA) {
  const ig = letturaMeta();
  if (!ig.ok) return fermo(ig.perche, true);
  const fb2 = String(cfg().FB_PAGE_ID_2 || '').trim();
  if (!/^\d{5,20}$/.test(fb2)) return fermo('FB_PAGE_ID_2 nel Config manca o non è un numero');
  const prima = {};
  for (const col of ['ig_user_id', 'fb_page_id']) { const t = cellaTropico(s, col); if (t.fermo) return t.fermo; prima[col] = t.attuale.trim(); }
  // Se le colonne _2 nascono in questo giro col punto a, oggi sono vuote per definizione.
  const nasce = colonneDiA.stato === 'da_fare' ? new Set((colonneClienti(s).manca || { a: [] }).a) : new Set();
  const ora = {}; const range = {}; let riga = null;
  for (const col of ['ig_user_id_2', 'fb_page_id_2']) {
    if (nasce.has(col)) { ora[col] = ''; continue; }
    const t = cellaTropico(s, col); if (t.fermo) return t.fermo;
    ora[col] = t.attuale; range[col] = t.range; riga = t.riga;
  }
  if (ig.id === prima.ig_user_id || ig.id === prima.fb_page_id) return fermo('l\'ID Instagram letto è uguale a un ID della prima coppia: non scrivo');
  if (fb2 === prima.fb_page_id || fb2 === prima.ig_user_id) return fermo('la pagina Facebook è uguale a un ID della prima coppia: non scrivo');
  const voluti = { ig_user_id_2: ig.id, fb_page_id_2: fb2 };
  if (ora.ig_user_id_2 === voluti.ig_user_id_2 && ora.fb_page_id_2 === voluti.fb_page_id_2) return aPosto();
  const piene = Object.keys(voluti).filter((k) => !vuota(ora[k]) && ora[k] !== voluti[k]);
  if (piene.length) return fermo(`${piene.join(' e ')} già ${piene.length > 1 ? 'piene' : 'piena'} con un valore diverso: non sovrascrivo`);
  const daScrivere = Object.keys(voluti).filter((k) => ora[k] !== voluti[k]);
  return { stato: 'da_fare', descr: `letto da Meta → ${daScrivere.join(' e ')}${riga ? ` nella riga ${riga}` : ''}, in formato testo`,
    struttura: [], valori: daScrivere.filter((k) => range[k]).map((k) => ({ range: range[k], values: [[voluti[k]]] })),
    ...(nasce.size ? { dipende: 'a' } : {}) };
}

function analizza(s) { const a = puntoA(s); return { a, b: puntoB(s), c: puntoC(s), d: puntoD(s), e: puntoE(s), f: puntoF(s), g: puntoG(s, a) }; }

const json = (items) => items.map((i) => i.json);
// ===== fine aiuti comuni =====

// Legge lo stato iniziale e decide. Scritture di struttura (batchUpdate) solo in modalità «vero», una chiamata per punto.
const stato = leggiStato(json($('Prepara letture').all()), json($input.all()));
const analisi = analizza(stato);
const vero = modalitaVera();
const base = { analisi, vero, errori_lettura: stato.errori };
const out = [];
if (vero) for (const p of PUNTI) {
  if (analisi[p].stato === 'da_fare' && analisi[p].struttura.length)
    out.push({ punto: p, url: `${urlFoglio()}:batchUpdate`, body: { requests: analisi[p].struttura } });
}
if (!out.length) return [{ json: { nulla: true, ...base } }];
return out.map((o, i) => ({ json: i === 0 ? { ...o, ...base } : o }));

// ===== Aiuti comuni di «Prepara foglio (una tantum)» =====
// Questo blocco è uguale in tutti i nodi Code: si modifica qui e si rigenera con costruisci.mjs.
const API = 'https://sheets.googleapis.com/v4/spreadsheets/';
const CLIENTI = 'Clienti';
const CALENDARIO = 'Calendario';
const APPROVAZIONI = 'Approvazioni storie';
const NUOVE_CLIENTI = ['ig_user_id_2', 'fb_page_id_2', 'campi_da_confermare'];
const NUOVE_CLIENTI_F = ['anteprime_con_persone'];
const COLONNE_TESTO = ['ig_user_id_2', 'fb_page_id_2'];
const CAL_A_T = ['id', 'cliente', 'tipo', 'piattaforme', 'data_ora', 'didascalia', 'primo_commento', 'media', 'copertina', 'stato',
  'esecuzione', 'link_ig', 'link_fb', 'pubblicato_il', 'errore', 'note', 'brief', 'tag_persone', 'collaboratori', 'luogo'];
const CAL_U_Z = ['stato_2', 'esecuzione_2', 'link_ig_2', 'link_fb_2', 'pubblicato_il_2', 'errore_2'];
const APP_INTESTAZIONI = ['data_ora', 'chiave', 'id_riga', 'cliente', 'esce_il', 'esito', 'scade_il', 'token', 'dettaglio'];
const TROPICO = 'tropico-latino';
const FRASI_TROPICO = 'Vi aspettiamo stasera in via Mazzini 77/A | Prenota il tuo tavolo: 0523 335932 | Margarita frozen o classico? | Aperitivo al bancone, si parte! | Due sale, più di 100 posti: portate tutti | Bienvenidos al Tropico! | Fajitas per due: si divide e si assaggia | Nachos e guacamole per cominciare | Anche vegetariano: burrito de verduras | Enchiladas rojas o verdes? Scegli tu | Queso fundido da condividere al tavolo | Venerdì e sabato aperti fino alle 2 | Cucina aperta fino alle 23, nel weekend 23:30 | Per finire in dolcezza: churros | Mousse al cioccolato e peperoncino, da provare';
const LINK_TROPICO = 'https://wa.me/393312173684';
const PUNTI = ['a', 'b', 'c', 'd', 'e', 'f', 'g'];
const ID_NUOVA_SCHEDA = 2026112201; // sheetId scelto da noi, così addSheet e intestazioni stanno in UNA chiamata atomica

const cfg = () => $('Config').first().json;
const modalitaVera = () => String(cfg().MODALITA || '').trim() === 'vero'; // qualunque altro valore = prova
const lettera = (i) => { let s = ''; let n = i + 1; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const intervallo = (titolo, a1) => `'${titolo.replace(/'/g, "''")}'` + (a1 ? `!${a1}` : '');
const urlFoglio = () => API + encodeURIComponent(cfg().SHEET_ID);
const cella = (riga, i) => (riga && riga[i] != null ? String(riga[i]) : '');
const vuota = (v) => String(v == null ? '' : v).trim() === '';
const virgolette = (v) => '«' + (String(v).length > 30 ? String(v).slice(0, 30) + '…' : String(v)) + '»';

// Le letture: struttura (solo sheets.properties) + valori delle tre schede. Righe intere, mai colonne oltre la griglia.
function letture() {
  const u = urlFoglio();
  return [
    { cosa: 'meta', url: `${u}?fields=sheets.properties` },
    { cosa: 'clienti', url: `${u}/values/${encodeURIComponent(intervallo(CLIENTI))}` },
    { cosa: 'calendario', url: `${u}/values/${encodeURIComponent(intervallo(CALENDARIO))}` },
    { cosa: 'approvazioni', url: `${u}/values/${encodeURIComponent(intervallo(APPROVAZIONI, '1:1'))}` },
  ];
}

// Esito di una risposta dell'HTTP Request (fullResponse + neverError, oppure {error} se la rete è caduta).
function esito(r) {
  if (!r) return { ok: false, errore: 'nessuna risposta' };
  if (r.error) return { ok: false, errore: 'rete: ' + String(r.error.message || r.error.description || JSON.stringify(r.error)).slice(0, 160) };
  const sc = Number(r.statusCode);
  if (sc >= 200 && sc < 300) return { ok: true, body: r.body || {} };
  const msg = r.body && r.body.error && r.body.error.message ? String(r.body.error.message) : String(r.statusMessage || '');
  return { ok: false, errore: `HTTP ${sc || '?'}: ${msg.slice(0, 160)}` };
}

// Mette insieme le risposte delle letture (stesso ordine delle richieste).
function leggiStato(richieste, risposte) {
  const s = { meta: null, valori: {}, errori: {} };
  richieste.forEach((q, i) => {
    const e = esito(risposte[i]);
    if (!e.ok) { s.errori[q.cosa] = e.errore; s.valori[q.cosa] = null; return; }
    if (q.cosa === 'meta') {
      s.meta = {};
      for (const sh of e.body.sheets || []) { const p = sh.properties || {}; s.meta[p.title] = { sheetId: p.sheetId, colonne: (p.gridProperties || {}).columnCount || 0 }; }
    } else s.valori[q.cosa] = e.body.values || [];
  });
  return s;
}

const fermo = (perche, api = false) => ({ stato: 'fermo', perche, api, struttura: [], valori: [] });
const aPosto = () => ({ stato: 'gia', struttura: [], valori: [] });
const errLettura = (s, cosa) => fermo(`non riesco a leggere (${s.errori[cosa] || s.errori.meta || 'errore'})`, true);

// Colonne nuove di Clienti: a) le 3 colonne, f) anteprime_con_persone. Stanno in fondo, una dopo l'altra:
// le posizioni si calcolano INSIEME (prima quelle di a, poi f) e la modifica di griglia/formato va in UN solo batchUpdate,
// sul punto a se ha qualcosa da fare, altrimenti sul punto f. Così due chiamate parallele non si pestano i piedi.
function colonneClienti(s) {
  if (!s.meta) return { fermo: errLettura(s, 'meta') };
  const m = s.meta[CLIENTI];
  if (!m) return { fermo: fermo('la scheda Clienti non esiste') };
  const righe = s.valori.clienti;
  if (righe == null) return { fermo: errLettura(s, 'clienti') };
  const int = (righe[0] || []).map((v) => String(v == null ? '' : v));
  const presenti = new Set(int.map((v) => v.trim()));
  const manca = { a: NUOVE_CLIENTI.filter((n) => !presenti.has(n)), f: NUOVE_CLIENTI_F.filter((n) => !presenti.has(n)) };
  const tutte = manca.a.concat(manca.f);
  if (!tutte.length) return { manca };
  let inizio = 0; int.forEach((v, i) => { if (!vuota(v)) inizio = i + 1; });
  if (righe.slice(1).some((r) => (r || []).slice(inizio).some((v) => !vuota(v))))
    return { manca, fermo: fermo(`ci sono dati a destra dell'ultima intestazione (dalla colonna ${lettera(inizio)}): non metto colonne sopra dati esistenti`) };
  const fine = inizio + tutte.length;
  const struttura = [];
  if (fine > m.colonne) struttura.push({ appendDimension: { sheetId: m.sheetId, dimension: 'COLUMNS', length: fine - m.colonne } });
  tutte.forEach((n, k) => {
    if (COLONNE_TESTO.includes(n)) struttura.push({ repeatCell: { range: { sheetId: m.sheetId, startColumnIndex: inizio + k, endColumnIndex: inizio + k + 1 },
      cell: { userEnteredFormat: { numberFormat: { type: 'TEXT', pattern: '@' } } }, fields: 'userEnteredFormat.numberFormat' } });
  });
  // Le intestazioni entrano nello STESSO batchUpdate (repeatCell con il testo, come in c): griglia, formato e nomi
  // nascono insieme o per niente. Così alla rilettura le colonne esistono già per nome e il punto g le ritrova.
  tutte.forEach((n, k) => struttura.push({ repeatCell: { range: { sheetId: m.sheetId, startRowIndex: 0, endRowIndex: 1, startColumnIndex: inizio + k, endColumnIndex: inizio + k + 1 },
    cell: { userEnteredValue: { stringValue: n } }, fields: 'userEnteredValue' } }));
  const allarga = fine > m.colonne ? fine - m.colonne : 0;
  return { manca, inizio, struttura, allarga, padrone: manca.a.length ? 'a' : 'f' };
}

function puntoColonne(s, p) {
  const c = colonneClienti(s);
  if (c.manca && !c.manca[p].length) return aPosto();
  if (c.fermo) return c.fermo;
  const da = c.inizio + (p === 'f' ? c.manca.a.length : 0);
  const nomi = c.manca[p]; const a = da + nomi.length - 1;
  const mia = c.padrone === p;
  const descr = `aggiunta di ${nomi.join(', ')} in ${lettera(da)}1${a > da ? '-' + lettera(a) + '1' : ''}`
    + (nomi.some((n) => COLONNE_TESTO.includes(n)) ? ' (ID in formato testo)' : '')
    + (p === 'f' ? ' (vuota = no, formato normale)' : '')
    + (mia && c.allarga ? `, griglia +${c.allarga} colonne` : '');
  return { stato: 'da_fare', descr, struttura: mia ? c.struttura : [], valori: [], ...(mia ? {} : { dipende: c.padrone }) };
}
const puntoA = (s) => puntoColonne(s, 'a');
const puntoF = (s) => puntoColonne(s, 'f');

function puntoB(s) {
  if (!s.meta) return errLettura(s, 'meta');
  const m = s.meta[CALENDARIO];
  if (!m) return fermo('la scheda Calendario non esiste');
  const righe = s.valori.calendario;
  if (righe == null) return errLettura(s, 'calendario');
  const int = righe[0] || [];
  const diverse = CAL_A_T.map((n, i) => (cella(int, i) === n ? null : `${lettera(i)}1 è ${virgolette(cella(int, i))} invece di ${virgolette(n)}`)).filter(Boolean);
  if (diverse.length) return fermo(`A1:T1 non sono le 20 intestazioni attese (${diverse.slice(0, 3).join('; ')}${diverse.length > 3 ? `; e altre ${diverse.length - 3}` : ''})`);
  const uz = CAL_U_Z.map((n, k) => cella(int, 20 + k));
  if (uz.every((v, k) => v === CAL_U_Z[k])) return aPosto();
  if (!uz.every(vuota)) {
    const altro = uz.map((v, k) => (vuota(v) || v === CAL_U_Z[k] ? null : `${lettera(20 + k)}1 = ${virgolette(v)}`)).filter(Boolean);
    return fermo(altro.length ? `U1:Z1 contengono altro (${altro.join('; ')}): non scrivo` : 'U1:Z1 sono compilate solo in parte: non scrivo, controlla a mano');
  }
  if (righe.slice(1).some((r) => (r || []).slice(20, 26).some((v) => !vuota(v)))) return fermo('ci sono già dati nelle colonne U-Z sotto intestazioni vuote: non scrivo');
  const struttura = m.colonne < 26 ? [{ appendDimension: { sheetId: m.sheetId, dimension: 'COLUMNS', length: 26 - m.colonne } }] : [];
  return { stato: 'da_fare', descr: 'intestazioni stato_2 … errore_2 in U1:Z1' + (struttura.length ? `, griglia +${26 - m.colonne} colonne` : ''),
    struttura, valori: [{ range: intervallo(CALENDARIO, 'U1:Z1'), values: [CAL_U_Z] }] };
}

function puntoC(s) {
  if (!s.meta) return errLettura(s, 'meta');
  const m = s.meta[APPROVAZIONI];
  if (!m) {
    let id = ID_NUOVA_SCHEDA; const usati = new Set(Object.values(s.meta).map((x) => x.sheetId));
    while (usati.has(id)) id += 1;
    const struttura = [{ addSheet: { properties: { sheetId: id, title: APPROVAZIONI, gridProperties: { rowCount: 1000, columnCount: 26 } } } }]
      .concat(APP_INTESTAZIONI.map((n, i) => ({ repeatCell: { range: { sheetId: id, startRowIndex: 0, endRowIndex: 1, startColumnIndex: i, endColumnIndex: i + 1 },
        cell: { userEnteredValue: { stringValue: n } }, fields: 'userEnteredValue' } })));
    return { stato: 'da_fare', descr: 'nuova scheda con le 9 intestazioni (data_ora … dettaglio)', struttura, valori: [] };
