  const int = righe[0] || [];
  const diff = APP_INTESTAZIONI.map((n, i) => (cella(int, i) === n ? null : `${lettera(i)}1 è ${virgolette(cella(int, i))} invece di ${virgolette(n)}`)).filter(Boolean);
  int.slice(9).forEach((v, k) => { if (!vuota(v)) diff.push(`${lettera(9 + k)}1 in più: ${virgolette(v)}`); });
  if (!diff.length) return aPosto();
  return fermo(`la scheda esiste già con intestazioni diverse (${diff.slice(0, 4).join('; ')}${diff.length > 4 ? `; e altre ${diff.length - 4}` : ''}): non la tocco`);
}

// La riga di tropico-latino (una sola) e la colonna per nome, nello stato letto.
function cellaTropico(s, colonna) {
  if (!s.meta) return { fermo: errLettura(s, 'meta') };
  if (!s.meta[CLIENTI]) return { fermo: fermo('la scheda Clienti non esiste') };
  const righe = s.valori.clienti;
  if (righe == null) return { fermo: errLettura(s, 'clienti') };
  const int = (righe[0] || []).map((v) => String(v == null ? '' : v).trim());
  const quante = (n) => int.filter((v) => v === n).length;
  if (quante('cliente') !== 1) return { fermo: fermo(quante('cliente') ? 'la colonna cliente compare più volte' : 'manca la colonna cliente') };
  if (quante(colonna) !== 1) return { fermo: fermo(quante(colonna) ? `la colonna ${colonna} compare più volte` : `manca la colonna ${colonna}`) };
  const ic = int.indexOf('cliente'); const col = int.indexOf(colonna);
  const trovate = []; righe.forEach((r, i) => { if (i > 0 && cella(r, ic).trim() === TROPICO) trovate.push(i + 1); });
  if (!trovate.length) return { fermo: fermo(`nessuna riga con cliente = ${TROPICO}`) };
  if (trovate.length > 1) return { fermo: fermo(`${TROPICO} compare in ${trovate.length} righe (righe ${trovate.join(', ')}): non so quale scrivere`) };
  const riga = trovate[0];
  return { riga, attuale: cella(righe[riga - 1], col), range: intervallo(CLIENTI, `${lettera(col)}${riga}`) };
}

function puntoD(s) {
  const t = cellaTropico(s, 'frasi_storie');
  if (t.fermo) return t.fermo;
  if (t.attuale === FRASI_TROPICO) return aPosto();
  return { stato: 'da_fare', descr: `nuovo testo in frasi_storie, riga ${t.riga} (prima: ${t.attuale ? t.attuale.length + ' caratteri' : 'vuota'})`,
    struttura: [], valori: [{ range: t.range, values: [[FRASI_TROPICO]] }] };
}

// e) link_prenotazione. Il numero non entra MAI nella descrizione: né il vecchio né il nuovo.
function puntoE(s) {
  const t = cellaTropico(s, 'link_prenotazione');
  if (t.fermo) return t.fermo;
  if (t.attuale === LINK_TROPICO) return aPosto();
  const prima = vuota(t.attuale) ? '(vuoto)' : (/wa\.me/i.test(t.attuale) ? 'wa.me/… (nascosto)' : '(nascosto)');
