const cfg = () => $('Config').first().json;
const modalitaVera = () => String(cfg().MODALITA || '').trim() === 'vero'; // qualunque altro valore = prova
const lettera = (i) => { let s = ''; let n = i + 1; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const intervallo = (titolo, a1) => `'${titolo.replace(/'/g, "''")}'` + (a1 ? `!${a1}` : '');
const urlFoglio = () => API + encodeURIComponent(cfg().SHEET_ID);
const cella = (riga, i) => (riga && riga[i] != null ? String(riga[i]) : '');
const vuota = (v) => String(v == null ? '' : v).trim() === '';
const virgolette = (v) => '«' + (String(v).length > 30 ? String(v).slice(0, 30) + '…' : String(v)) + '»';

// Le letture: struttura (solo sheets.properties) + valori delle tre schede. Righe intere, mai colonne oltre la griglia.
function letture() {
  const u = urlFoglio();
  return [
    { cosa: 'meta', url: `${u}?fields=sheets.properties` },
    { cosa: 'clienti', url: `${u}/values/${encodeURIComponent(intervallo(CLIENTI))}` },
    { cosa: 'calendario', url: `${u}/values/${encodeURIComponent(intervallo(CALENDARIO))}` },
    { cosa: 'approvazioni', url: `${u}/values/${encodeURIComponent(intervallo(APPROVAZIONI, '1:1'))}` },
  ];
}

// Esito di una risposta dell'HTTP Request (fullResponse + neverError, oppure {error} se la rete è caduta).
function esito(r) {
  if (!r) return { ok: false, errore: 'nessuna risposta' };
  if (r.error) return { ok: false, errore: 'rete: ' + String(r.error.message || r.error.description || JSON.stringify(r.error)).slice(0, 160) };
  const sc = Number(r.statusCode);
  if (sc >= 200 && sc < 300) return { ok: true, body: r.body || {} };
  const msg = r.body && r.body.error && r.body.error.message ? String(r.body.error.message) : String(r.statusMessage || '');
  return { ok: false, errore: `HTTP ${sc || '?'}: ${msg.slice(0, 160)}` };
}

// Mette insieme le risposte delle letture (stesso ordine delle richieste).
function leggiStato(richieste, risposte) {
  const s = { meta: null, valori: {}, errori: {} };
  richieste.forEach((q, i) => {
    const e = esito(risposte[i]);
    if (!e.ok) { s.errori[q.cosa] = e.errore; s.valori[q.cosa] = null; return; }
    if (q.cosa === 'meta') {
      s.meta = {};
      for (const sh of e.body.sheets || []) { const p = sh.properties || {}; s.meta[p.title] = { sheetId: p.sheetId, colonne: (p.gridProperties || {}).columnCount || 0 }; }
    } else s.valori[q.cosa] = e.body.values || [];
  });
  return s;
}

const fermo = (perche, api = false) => ({ stato: 'fermo', perche, api, struttura: [], valori: [] });
const aPosto = () => ({ stato: 'gia', struttura: [], valori: [] });
const errLettura = (s, cosa) => fermo(`non riesco a leggere (${s.errori[cosa] || s.errori.meta || 'errore'})`, true);

// Colonne nuove di Clienti: a) le 3 colonne, f) anteprime_con_persone. Stanno in fondo, una dopo l'altra:
// le posizioni si calcolano INSIEME (prima quelle di a, poi f) e la modifica di griglia/formato va in UN solo batchUpdate,
// sul punto a se ha qualcosa da fare, altrimenti sul punto f. Così due chiamate parallele non si pestano i piedi.
function colonneClienti(s) {
  if (!s.meta) return { fermo: errLettura(s, 'meta') };
  const m = s.meta[CLIENTI];
  if (!m) return { fermo: fermo('la scheda Clienti non esiste') };
  const righe = s.valori.clienti;
  if (righe == null) return { fermo: errLettura(s, 'clienti') };
  const int = (righe[0] || []).map((v) => String(v == null ? '' : v));
  const presenti = new Set(int.map((v) => v.trim()));
  const manca = { a: NUOVE_CLIENTI.filter((n) => !presenti.has(n)), f: NUOVE_CLIENTI_F.filter((n) => !presenti.has(n)) };
  const tutte = manca.a.concat(manca.f);
  if (!tutte.length) return { manca };
  let inizio = 0; int.forEach((v, i) => { if (!vuota(v)) inizio = i + 1; });
  if (righe.slice(1).some((r) => (r || []).slice(inizio).some((v) => !vuota(v))))
    return { manca, fermo: fermo(`ci sono dati a destra dell'ultima intestazione (dalla colonna ${lettera(inizio)}): non metto colonne sopra dati esistenti`) };
  const fine = inizio + tutte.length;
  const struttura = [];
  if (fine > m.colonne) struttura.push({ appendDimension: { sheetId: m.sheetId, dimension: 'COLUMNS', length: fine - m.colonne } });
  tutte.forEach((n, k) => {
    if (COLONNE_TESTO.includes(n)) struttura.push({ repeatCell: { range: { sheetId: m.sheetId, startColumnIndex: inizio + k, endColumnIndex: inizio + k + 1 },
      cell: { userEnteredFormat: { numberFormat: { type: 'TEXT', pattern: '@' } } }, fields: 'userEnteredFormat.numberFormat' } });
  });
  // Le intestazioni entrano nello STESSO batchUpdate (repeatCell con il testo, come in c): griglia, formato e nomi
  // nascono insieme o per niente. Così alla rilettura le colonne esistono già per nome e il punto g le ritrova.
  tutte.forEach((n, k) => struttura.push({ repeatCell: { range: { sheetId: m.sheetId, startRowIndex: 0, endRowIndex: 1, startColumnIndex: inizio + k, endColumnIndex: inizio + k + 1 },
    cell: { userEnteredValue: { stringValue: n } }, fields: 'userEnteredValue' } }));
  const allarga = fine > m.colonne ? fine - m.colonne : 0;
  return { manca, inizio, struttura, allarga, padrone: manca.a.length ? 'a' : 'f' };
}

function puntoColonne(s, p) {
  const c = colonneClienti(s);
