  const nomi = c.manca[p]; const a = da + nomi.length - 1;
  const mia = c.padrone === p;
  const descr = `aggiunta di ${nomi.join(', ')} in ${lettera(da)}1${a > da ? '-' + lettera(a) + '1' : ''}`
    + (nomi.some((n) => COLONNE_TESTO.includes(n)) ? ' (ID in formato testo)' : '')
    + (p === 'f' ? ' (vuota = no, formato normale)' : '')
    + (mia && c.allarga ? `, griglia +${c.allarga} colonne` : '');
  return { stato: 'da_fare', descr, struttura: mia ? c.struttura : [], valori: [], ...(mia ? {} : { dipende: c.padrone }) };
}
const puntoA = (s) => puntoColonne(s, 'a');
const puntoF = (s) => puntoColonne(s, 'f');

function puntoB(s) {
