// ===== Aiuti comuni di «Prepara foglio (una tantum)» =====
// Questo blocco è uguale in tutti i nodi Code: si modifica qui e si rigenera con costruisci.mjs.
const API = 'https://sheets.googleapis.com/v4/spreadsheets/';
const CLIENTI = 'Clienti';
const CALENDARIO = 'Calendario';
const APPROVAZIONI = 'Approvazioni storie';
const NUOVE_CLIENTI = ['ig_user_id_2', 'fb_page_id_2', 'campi_da_confermare'];
const NUOVE_CLIENTI_F = ['anteprime_con_persone'];
const COLONNE_TESTO = ['ig_user_id_2', 'fb_page_id_2'];
const CAL_A_T = ['id', 'cliente', 'tipo', 'piattaforme', 'data_ora', 'didascalia', 'primo_commento', 'media', 'copertina', 'stato',
  'esecuzione', 'link_ig', 'link_fb', 'pubblicato_il', 'errore', 'note', 'brief', 'tag_persone', 'collaboratori', 'luogo'];
const CAL_U_Z = ['stato_2', 'esecuzione_2', 'link_ig_2', 'link_fb_2', 'pubblicato_il_2', 'errore_2'];
const APP_INTESTAZIONI = ['data_ora', 'chiave', 'id_riga', 'cliente', 'esce_il', 'esito', 'scade_il', 'token', 'dettaglio'];
