// g) La lettura da Meta: buona SOLO con status 200 e instagram_business_account.id di sole cifre, 15-20.
// Il motivo è sempre un testo nostro: il messaggio d'errore di Meta non esce mai (al massimo il codice HTTP).
function letturaMeta() {
  let r;
  try { r = $('Leggi Meta').first().json; } catch (e) { return { ok: false, perche: 'lettura da Meta non eseguita' }; }
  if (!r || r.error) return { ok: false, perche: 'lettura da Meta non riuscita (rete)' };
  const sc = Number(r.statusCode);
  if (sc !== 200) return { ok: false, perche: `lettura da Meta non riuscita (codice HTTP ${Number.isFinite(sc) ? sc : '?'})` };
  const iba = r.body && r.body.instagram_business_account;
  const id = iba && iba.id;
  if (typeof id !== 'string') return { ok: false, perche: 'lettura da Meta senza account Instagram collegato (codice HTTP 200)' };
  if (!/^\d{15,20}$/.test(id)) return { ok: false, perche: 'lettura da Meta con un ID Instagram di forma inattesa (codice HTTP 200)' };
  return { ok: true, id };
}

// g) Scrive ig_user_id_2 (letto) e fb_page_id_2 (da Config) nella riga di tropico-latino. MAI ID nei testi.
function puntoG(s, colonneDiA) {
  const ig = letturaMeta();
  if (!ig.ok) return fermo(ig.perche, true);
  const fb2 = String(cfg().FB_PAGE_ID_2 || '').trim();
  if (!/^\d{5,20}$/.test(fb2)) return fermo('FB_PAGE_ID_2 nel Config manca o non è un numero');
  const prima = {};
  for (const col of ['ig_user_id', 'fb_page_id']) { const t = cellaTropico(s, col); if (t.fermo) return t.fermo; prima[col] = t.attuale.trim(); }
  // Se le colonne _2 nascono in questo giro col punto a, oggi sono vuote per definizione.
  const nasce = colonneDiA.stato === 'da_fare' ? new Set((colonneClienti(s).manca || { a: [] }).a) : new Set();
  const ora = {}; const range = {}; let riga = null;
  for (const col of ['ig_user_id_2', 'fb_page_id_2']) {
    if (nasce.has(col)) { ora[col] = ''; continue; }
    const t = cellaTropico(s, col); if (t.fermo) return t.fermo;
    ora[col] = t.attuale; range[col] = t.range; riga = t.riga;
  }
  if (ig.id === prima.ig_user_id || ig.id === prima.fb_page_id) return fermo('l\'ID Instagram letto è uguale a un ID della prima coppia: non scrivo');
  if (fb2 === prima.fb_page_id || fb2 === prima.ig_user_id) return fermo('la pagina Facebook è uguale a un ID della prima coppia: non scrivo');
  const voluti = { ig_user_id_2: ig.id, fb_page_id_2: fb2 };
  if (ora.ig_user_id_2 === voluti.ig_user_id_2 && ora.fb_page_id_2 === voluti.fb_page_id_2) return aPosto();
  const piene = Object.keys(voluti).filter((k) => !vuota(ora[k]) && ora[k] !== voluti[k]);
  if (piene.length) return fermo(`${piene.join(' e ')} già ${piene.length > 1 ? 'piene' : 'piena'} con un valore diverso: non sovrascrivo`);
  const daScrivere = Object.keys(voluti).filter((k) => ora[k] !== voluti[k]);
  return { stato: 'da_fare', descr: `letto da Meta → ${daScrivere.join(' e ')}${riga ? ` nella riga ${riga}` : ''}, in formato testo`,
    struttura: [], valori: daScrivere.filter((k) => range[k]).map((k) => ({ range: range[k], values: [[voluti[k]]] })),
    ...(nasce.size ? { dipende: 'a' } : {}) };
}

function analizza(s) { const a = puntoA(s); return { a, b: puntoB(s), c: puntoC(s), d: puntoD(s), e: puntoE(s), f: puntoF(s), g: puntoG(s, a) }; }

const json = (items) => items.map((i) => i.json);
// ===== fine aiuti comuni =====

// Confronta prima/dopo e scrive il riepilogo Telegram punto per punto. Nessun valore di celle Meta finisce nel testo.
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const primo = $('Piano struttura').first().json;
const an1 = primo.analisi; const vero = primo.vero;
const esiti1 = $('Prepara riletture').first().json.esiti_struttura || [];
const pv = $('Piano valori').first().json;
const bloccati = pv.bloccati || {};
const esiti2 = $('Prepara verifica').first().json.esiti_valori || [];
const stato3 = leggiStato(json($('Prepara verifica').all()), json($input.all()));
const an3 = analizza(stato3);
const TITOLI = { a: 'Clienti, 3 colonne nuove', b: 'Calendario, colonne U-Z', c: 'Scheda «Approvazioni storie»', d: `frasi_storie di ${TROPICO}`, e: `link di prenotazione di ${TROPICO}`, f: 'Clienti, colonna anteprime_con_persone', g: `seconda coppia di ID di ${TROPICO}` };
const gravi = [];
const righe = [];
let daFare = 0;
for (const p of PUNTI) {
  const x = an1[p];
  let t;
  if (x.stato === 'gia') t = 'già a posto';
  else if (x.stato === 'fermo') { t = `fermo perché ${x.perche}`; if (x.api) gravi.push(`${p}) ${x.perche}`); }
  else if (!vero) { t = `avrei fatto: ${x.descr}`; daFare += 1; }
  else {
    const dip = x.dipende || null; // f e g possono viaggiare sulle chiamate del punto a
    const err = esiti1.concat(esiti2).filter((e) => (e.punto === p || e.punto === dip) && !e.ok).map((e) => (e.punto === p ? e.errore : `chiamata del punto ${dip}: ${e.errore}`));
    if (err.length) { t = `fermo perché errore delle API (${err.join('; ')})`; gravi.push(`${p}) ${err.join('; ')}`); }
    else if (bloccati[p]) { t = `fermo perché ${bloccati[p]}`; gravi.push(`${p}) ${bloccati[p]}`); }
    else if (an3[p].stato === 'gia') t = `fatto: ${x.descr} (verificato alla rilettura)`;
    else { const why = an3[p].stato === 'fermo' ? an3[p].perche : 'il foglio non risulta ancora come atteso'; t = `fatto, ma la verifica non torna: ${why}`; gravi.push(`${p}) verifica: ${why}`); }
  }
  righe.push(`<b>${p})</b> ${esc(TITOLI[p])}: ${esc(t)}`);
}
// Le letture di verifica devono riuscire, altrimenti in «vero» non posso dire «fatto».
const errVer = Object.entries(stato3.errori).filter(([k]) => !(k === 'approvazioni' && stato3.meta && !stato3.meta[APPROVAZIONI]));
if (vero && errVer.length) gravi.push('rilettura finale: ' + errVer.map(([k, v]) => `${k} ${v}`).join('; '));
const testa = `<b>Prepara foglio (una tantum)</b> — ${vero ? 'modalità VERO' : 'modalità PROVA: nessuna scrittura'}`;
const coda = [];
if (!vero && an1.d.stato === 'da_fare') {
  const frasi = FRASI_TROPICO.split(' | ');
  coda.push(`Frasi che scriverei (${frasi.length}, accorciate): ${esc(frasi.slice(0, 4).map((f) => (f.length > 24 ? f.slice(0, 24) + '…' : f)).join(' | '))} … e altre ${frasi.length - 4}`);
}
if (!vero && daFare) coda.push('Per eseguire davvero: nel nodo Config metti MODALITA = vero e rilancia.');
if (vero && /<\/b> [^:]+: fermo/.test(righe[PUNTI.indexOf('g')])) coda.push('ig_user_id_2 e fb_page_id_2 non sono stati scritti: vedi il punto g.');
if (gravi.length) coda.push(`<b>Errore grave</b>: ${esc(gravi.join(' · '))}`);
// Ultima difesa: nessun numero di telefono nel messaggio, qualunque cosa sia finita nei testi sopra.
const senzaNumeri = (t) => t.replace(/\+?\d[\d .]{7,}\d/g, '(numero nascosto)');
let testo = [testa, '', ...righe, '', ...coda].join('\n');
if (testo.length > 3900) testo = testo.replace(/<\/?b>/g, '').slice(0, 3880).replace(/&[a-z]*$/, '') + '\n…'; // senza tag, così l'HTML resta valido
testo = senzaNumeri(testo);
return [{ json: { testo, grave: gravi.length > 0, motivo_grave: gravi.length ? senzaNumeri('Prepara foglio: ' + gravi.join(' · ').slice(0, 900)) : '' } }];
